// Typed reader over the compiled rulebook.json. Server-side only (imported in
// server components). The JSON is generated by scripts/build-rulebook.mjs.
import rulebook from "@/public/rulebook.json";

export type Confidence = "verified" | "outdated" | "unverified";

export interface Course {
  code: string;
  title: string;
  avail?: string[];
  level?: string;
}

export interface Specialization {
  slug: string;
  name: string;
  confidence: Confidence;
  note?: string;
  required_mpe: string[];
  design_electives: Course[];
  technical_electives: Course[];
  change_flag?: string;
}

const DEFAULT_COHORT = "ntu/eee/ay2025-26";

function cohort(key: string = DEFAULT_COHORT) {
  const c = (rulebook as any).cohorts[key];
  if (!c) throw new Error(`Cohort ${key} not found in rulebook.json`);
  return c;
}

export function getMeta(key?: string) {
  return cohort(key).meta;
}

export function getDegree(key?: string) {
  return cohort(key).degree;
}

export function getGrading(key?: string) {
  return cohort(key).grading;
}

export function getAdmissions(key?: string) {
  return cohort(key).admissions;
}

export function getCareers(key?: string) {
  return cohort(key).careers;
}

export function getSpecializations(key?: string): Specialization[] {
  return cohort(key).specializations.specializations;
}

export function getSpecialization(slug: string, key?: string): Specialization | undefined {
  return getSpecializations(key).find((s) => s.slug === slug);
}

export function getRecognitionRules(key?: string) {
  return cohort(key).specializations.recognition_rules;
}

export function getCareerForSpec(slug: string, key?: string) {
  return getCareers(key).specialization_career_map?.map?.[slug];
}

export function cohortLabel(key: string = DEFAULT_COHORT) {
  const m = cohort(key).meta.cohort;
  return `${m.university.toUpperCase()} ${m.programme.toUpperCase()} · AY${m.academic_year}`;
}

export const ACTIVE_COHORT = DEFAULT_COHORT;
